            for (int i = 1; i <= maxRetries; i++)

            {

                try

                {

                    var result = await _tariffViewModel.GetRateTables();

                    if (result.Success)

                    {

                        try

                        {

                            if (result.Collection == null)

                            {

                                SendDesktopAlert("API Connection was successful. ERROR: Data not retrieved", "ERROR");

